<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{content.name||'商品详情'}}</h2><p>{{g.storeName||'商户名称未提供'}} <StatusTag :value="g.reviewStatus"/><StatusTag :value="g.marketStatus"/><Tag :color="g.forcedOff?'red':'default'">{{g.forcedOff?'受监管下架':'未受监管'}}</Tag></p><p v-if="selected" class="ui-meta">商品 {{g.id}} · 内容 v{{g.contentVersion}} · 数据 v{{g.version}} · 当前查看 {{historical?'历史送审版本':'当前版本'}}</p></div><div class="ui-actions"><Button @click="back">返回{{review?'审核':'监管'}}列表</Button><Button @click="reload">重新读取</Button></div></header><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><template v-if="selected"><Alert v-if="historical" type="warning" show-icon>只读历史送审版本。<Button type="text" @click="current">返回当前内容</Button></Alert><Alert v-if="snapshotMissing" type="error">当前送审快照不可读，不能用编辑稿替代审核。</Alert><Tabs v-model="tab" :animated="false"><TabPane label="商品内容与图片" name="overview"><DetailSection title="商品主信息"><FieldRow label="商品名称" :value="content.name"/><FieldRow label="商品卖点" :value="content.subtitle"/><FieldRow label="所属商户" :value="g.storeName"/><FieldRow label="单位" :value="contentUnitName"/><FieldRow label="类目（当前字典名）" :value="contentCategoryName" wide/><FieldRow label="品牌" :value="historical?(content.brandId?'该版本品牌名称未提供（'+content.brandId+'）':'未提供'):selected.brandName||(content.brandId?'名称未提供（'+content.brandId+'）':'未提供')"/><FieldRow label="备注" :value="content.note" wide/></DetailSection><DetailSection title="商品图片" :grid="false"><div style="display:flex;gap:16px;flex-wrap:wrap"><ProductImage v-for="id in content.galleryFileIds||[]" :key="id" :file-id="id" :alt="content.name" large/></div></DetailSection><DetailSection title="图文详情" :grid="false"><template v-for="(block,index) in content.detailBlocks||[]"><p v-if="block.type==='text'" :key="index" style="white-space:pre-wrap;line-height:1.9;margin:12px 0">{{block.text}}</p><ProductImage v-else-if="block.type==='image'" :key="index" :file-id="block.fileId" large/></template></DetailSection></TabPane><TabPane label="SKU规格与库存" name="skus"><SkuTable :rows="displaySkus" :live="selected.skus" :snapshot="!!reviewSnapshot&&(review||historical)"/></TabPane><TabPane label="履约配置" name="fulfillment"><DetailSection title="商品配置与当前有效方式" :grid="false"><p v-for="(name,method) in methods" :key="method" class="ui-two-line">{{name}}：{{(content.methods||[]).includes(method)?'该内容版本已选':'未选'}}；{{(g.effectiveMethods||[]).includes(method)?'当前有效':'当前无效或未配置'}}</p><p class="ui-note">历史内容展示所选方式；当前有效性读取当前事实，不伪造历史点位。</p><Button v-if="can('fulfillment.inspect')" @click="link('/s1/fulfillment',{targetStore:g.storeId})">核查商户方式与点位</Button></DetailSection><Eligibility v-if="can('store.read')" :embedded-store="g.storeId"/></TabPane><TabPane label="本次变更／送审版本" name="submission"><DetailSection title="送审依据"><FieldRow label="查看内容版本" :value="reviewSnapshot&&reviewSnapshot.contentVersion"/><FieldRow label="送审时间" :value="date(reviewSnapshot&&reviewSnapshot.submittedAt)"/><FieldRow label="当前批准版本" :value="g.approvedVersion"/><FieldRow label="当前监管原因" :value="g.forcedReason" wide/></DetailSection><p class="ui-note">内容关键变更会下架重审；库存和成本独立变化不改写送审内容。</p><Table :columns="changeColumns" :data="changes" no-data-text="没有可对照的前次送审版本"/></TabPane><TabPane label="审核记录" name="reviews"><HistoryTable :records="selected.reviews.map(r=>({...r,revision:r.contentVersion,status:r.decision||'SUBMITTED'}))" :columns="reviewColumns"><template slot="operations" slot-scope="{row}"><Button size="small" @click="viewVersion(row.contentVersion)">查看送审快照</Button></template></HistoryTable></TabPane><TabPane label="监管记录" name="regulation"><HistoryTable :records="selected.regulationHistory" :columns="regulationColumns"/></TabPane></Tabs><footer class="ui-footer-actions"><Button @click="back">返回列表</Button><template v-if="reviewable"><Button type="error" :disabled="blocked" @click="execute('reject')">驳回当前内容</Button><Button type="primary" :disabled="blocked" @click="execute('approve')">批准内容版本 {{g.contentVersion}}</Button></template><Button v-if="!review&&!historical&&can('goods.supervise')" type="warning" :disabled="blocked" @click="execute(g.forcedOff?'release':'force-off')">{{g.forcedOff?'解除管制并保持下架':'强制下架'}}</Button></footer></template></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';import DetailSection from './components/DetailSection';import FieldRow from './components/FieldRow';import ProductImage from './components/ProductImage';import SkuTable from './components/SkuTable';import HistoryTable from './components/HistoryTable';import Eligibility from './Eligibility';export default {mixins:[page],components:{PageStatus,StatusTag,DetailSection,FieldRow,ProductImage,SkuTable,HistoryTable,Eligibility},data:()=>({contentUnitName:'未提供',contentCategoryName:'未提供',reviewColumns:[{title:'内容版本',key:'revision',width:100},{title:'决定',slot:'state',width:110},{title:'审核人',key:'reviewerName',minWidth:140},{title:'时间',slot:'time',minWidth:185},{title:'意见',key:'reason',minWidth:200},{title:'操作',slot:'operations',width:150}],regulationColumns:[{title:'时间',slot:'time',minWidth:185},{title:'操作',slot:'action',minWidth:130},{title:'操作人',key:'operatorName',minWidth:130},{title:'原版本',key:'beforeVersion',width:90},{title:'新版本',key:'afterVersion',width:90},{title:'原因',key:'reason',minWidth:210}],changeColumns:[{title:'内容项',key:'name',width:150},{title:'前次送审',key:'before',minWidth:220},{title:'本次送审',key:'after',minWidth:220}]}),computed:{review(){return this.$route.path.startsWith('/s1/reviews/');},historical(){return !!this.$route.query.contentRevision;},g(){return this.selected&&this.selected.goods||{};},reviewSnapshot(){if(!this.selected)return null;const version=this.$route.query.contentRevision?Number(this.$route.query.contentRevision):this.g.contentVersion;return this.selected.reviews.find(r=>r.contentVersion===version)||null;},snapshotMissing(){return this.review&&this.g.reviewStatus==='SUBMITTED'&&!this.reviewSnapshot;},content(){if(this.reviewSnapshot&&(this.review||this.historical))return this.reviewSnapshot.submitted.content;return this.snapshotMissing?{}:this.selected&&this.selected.payload||{};},displaySkus(){return this.reviewSnapshot&&(this.review||this.historical)?this.reviewSnapshot.submitted.skus:this.selected.skus;},reviewable(){return this.review&&!this.historical&&!this.snapshotMissing&&this.g.reviewStatus==='SUBMITTED'&&this.can('goods.review');},changes(){if(!this.reviewSnapshot)return [];const previous=this.selected.reviews.filter(r=>r.contentVersion<this.reviewSnapshot.contentVersion).sort((a,b)=>b.contentVersion-a.contentVersion)[0];if(!previous)return [];const old=previous.submitted.content,now=this.reviewSnapshot.submitted.content;return [['name','名称'],['subtitle','卖点'],['categoryId','类目编号'],['unitId','单位编号'],['methods','履约方式']].filter(([key])=>JSON.stringify(old[key])!==JSON.stringify(now[key])).map(([key,name])=>({name,before:Array.isArray(old[key])?old[key].map(v=>this.methods[v]||v).join('、'):this.text(old[key]),after:Array.isArray(now[key])?now[key].map(v=>this.methods[v]||v).join('、'):this.text(now[key])}));}},watch:{'$route.fullPath'(){this.tab='overview';this.reload();}},mounted(){this.reload();},methods:{async resolveContentNames(){const id=this.g.id,version=this.$route.query.contentRevision,content=this.content;this.contentUnitName='未提供';this.contentCategoryName='未提供';try{const [c,u]=await Promise.all([content.categoryId?this.ui('/lookups/categories',{selected:content.categoryId,purpose:'goods',pageSize:1}):Promise.resolve({records:[]}),content.unitId?this.ui('/lookups/units',{selected:content.unitId,pageSize:1}):Promise.resolve({records:[]})]);if(this.selected&&this.g.id===id&&this.$route.query.contentRevision===version){this.contentCategoryName=c.records[0]?.path||'该内容版本类目名称未提供';this.contentUnitName=u.records[0]?.name||'该内容版本单位名称未提供';}}catch(e){if(this.selected&&this.g.id===id)this.error=e.message;}},reload(){return this.latest(()=>this.ui('/goods/'+this.$route.params.id),v=>{this.selected=v;this.resolveContentNames();},()=>{this.selected=null;});},viewVersion(version){this.$router.push({path:this.$route.path,query:{...this.$route.query,contentRevision:String(version)}});},current(){const query={...this.$route.query};delete query.contentRevision;this.$router.replace({path:this.$route.path,query});},async execute(action){if((action==='approve'||action==='reject')&&!this.reviewable)return;const titles={approve:'批准当前送审内容',reject:'驳回当前送审内容','force-off':'强制下架当前商品',release:'解除监管后仍保持下架'};const result=await this.command('/goods/'+this.g.id+'/'+action,titles[action],{expectedVersion:this.g.version,contentVersion:this.g.contentVersion},this.content.name+' · '+this.g.storeName+' · 内容 v'+this.g.contentVersion+'。不修改库存、成本或产生交易。');if(result)await this.reload();}}};</script>
